import { useRef } from "react";
import { ARTEMIS_EASE_IN_OUT, ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { NumberTicker } from "./02-floating-gallery/number-ticker";
import type { ArtemisCtaContent } from "../content";
const DEFAULT = {
    headline: "Turn \u201Csomeday\u201D into Saturday.",
    subhead: "Find a quiet trail, a tiny cabin, or a town you\u2019ve never heard of. Save your favorites and take the long way there.",
