const FLOAT_PX = 14;
const FLOAT_SECONDS = 8;
const FLOAT_STEP_SECONDS = 0.5;
const INSTANT = { duration: 0 } as const;
/** Where each photo floats, in the order `images` fills them. */
const TILES = [
    "art:-left-10 art:-top-20 art:-rotate-25 art:@min-[768px]/artemis:-left-12 art:@min-[768px]/artemis:-top-16",
    "art:-right-10 art:-top-20 art:rotate-25 art:@min-[768px]/artemis:-right-8 art:@min-[768px]/artemis:-top-14",
    "art:-left-20 art:top-40 art:-rotate-25 art:hidden art:@min-[768px]/artemis:block",
    "art:-right-16 art:top-44 art:rotate-25 art:hidden art:@min-[768px]/artemis:block",
    "art:-left-10 art:top-96 art:-rotate-25 art:hidden art:@min-[768px]/artemis:block",
    "art:-right-6 art:top-96 art:rotate-25 art:hidden art:@min-[768px]/artemis:block",
] as const;
const LINK_CLASS = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:h-9 art:text-sm art:after:absolute art:after:inset-x-0 art:after:-inset-y-1 art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-foreground art:dark:focus-visible:outline-background art:rounded-full";
export default function CtaSectionsFloatingGallery({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
const artemisInstanceId=useId();

    const sectionRef = useRef<HTMLElement>(null);
    const inView = useInView(sectionRef, { once: true, amount: 0.2 });
    const reduce = useReducedMotion();
    const play = inView;
    const press = {
        whileHover: reduce ? undefined : { scale: 1.01 },
        whileTap: reduce ? undefined : { scale: 0.99 },
        transition: ARTEMIS_SPRING_PRESS,
    };
    return (<MotionConfig reducedMotion="user">
      <section ref={sectionRef} aria-labelledby={`${artemisInstanceId}-graphic`} className="art:w-full art:px-4 art:py-8 art:@min-[768px]/artemis:px-8 art:@min-[768px]/artemis:py-12">
        <div className="art:relative art:isolate art:mx-auto art:max-w-7xl art:overflow-hidden art:rounded-3xl art:bg-background art:text-foreground art:dark:bg-foreground art:dark:text-background">
          <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:-z-10 art:bg-cover art:bg-[position:72%_center] art:@min-[768px]/artemis:bg-center"/>
          <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden art:[mask-image:linear-gradient(to_bottom,black_30%,transparent_92%)] art:@min-[768px]/artemis:[mask-image:linear-gradient(to_bottom,black_30%,transparent_100%),linear-gradient(to_right,black,transparent_30%,transparent_70%,black)] art:@min-[768px]/artemis:[mask-composite:intersect]">
            {copy.images.slice(0, TILES.length).map((image, i) => (<div key={TILES[i]} className={`art:absolute art:w-32 art:@min-[768px]/artemis:w-44 art:@min-[1024px]/artemis:w-56 ${TILES[i]}`}>
                <motion.div className="art:aspect-[4/5] art:overflow-hidden art:rounded-2xl art:border art:border-foreground/20 art:bg-background art:p-1.5 art:dark:border-background/20 art:dark:bg-foreground" animate={play ? { y: [0, (i % 2 === 0 ? -1 : 1) * FLOAT_PX, 0] } : undefined} transition={{
                duration: FLOAT_SECONDS + i * FLOAT_STEP_SECONDS,
                ease: ARTEMIS_EASE_IN_OUT,
                repeat: Infinity,
            }}>
                  <img src={image.src} alt={image.alt} width="480" height="600" loading="lazy" decoding="async" className="art:size-full art:rounded-xl art:object-cover"/>
                </motion.div>
              </div>))}
          </div>
          <div className="art:relative art:px-5 art:pt-28 art:pb-10 art:@min-[768px]/artemis:px-12 art:@min-[768px]/artemis:pt-24 art:@min-[768px]/artemis:pb-16 art:@min-[1024px]/artemis:pt-28 art:@min-[1024px]/artemis:pb-20">
            <motion.div className="art:mx-auto art:flex art:max-w-xl art:flex-col art:items-center art:text-center art:@min-[768px]/artemis:max-w-[60%]" initial={{ opacity: 0, y: 18 }} animate={play || reduce ? { opacity: 1, y: 0 } : undefined} transition={reduce ? INSTANT : { duration: 0.7, ease: ARTEMIS_EASE_OUT }}>
              <h2 id={`${artemisInstanceId}-graphic`} className="art:max-w-lg art:text-balance art:text-4xl art:font-medium art:tracking-tight">
                {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
              </h2>
              <p className="art:mt-5 art:max-w-md art:text-pretty art:text-sm art:leading-relaxed art:text-foreground/80 art:@min-[768px]/artemis:text-base art:dark:text-background/80">
                {copy.subhead}
              </p>
              <div className="art:mt-8 art:flex art:w-full art:max-w-64 art:flex-col art:items-stretch art:justify-center art:gap-3 art:@min-[768px]/artemis:mt-9 art:@min-[768px]/artemis:max-w-none art:@min-[768px]/artemis:flex-row art:@min-[768px]/artemis:flex-wrap art:@min-[768px]/artemis:items-center">
                <motion.a className={LINK_CLASS} href={copy.cta.href} tabIndex={0} {...press}>
                  <svg aria-hidden="true" viewBox="0 0 24 24" className="art:size-4 art:shrink-0" fill="currentColor">
                    <path d="M17.05 12.54c.03 3.18 2.79 4.24 2.82 4.25-.02.08-.44 1.51-1.45 2.99-.88 1.28-1.8 2.56-3.24 2.59-1.41.03-1.87-.84-3.49-.84-1.61 0-2.12.81-3.46.87-1.39.05-2.45-1.39-3.34-2.66-1.81-2.61-3.19-7.38-1.33-10.6.93-1.6 2.59-2.61 4.39-2.64 1.37-.03 2.66.92 3.49.92.83 0 2.39-1.14 4.03-.97.69.03 2.61.28 3.84 2.08-.1.06-2.29 1.33-2.26 4.01ZM14.4 4.71c.74-.9 1.24-2.15 1.1-3.4-1.07.04-2.37.71-3.14 1.61-.69.8-1.29 2.08-1.13 3.31 1.19.09 2.41-.61 3.17-1.52Z"/>
                  </svg>
                  {copy.cta.label}
                </motion.a>
                <motion.a className={LINK_CLASS} href={copy.secondaryCta.href} tabIndex={0} {...press}>
                  <svg aria-hidden="true" viewBox="0 0 24 24" className="art:size-4 art:shrink-0" fill="currentColor">
                    <path d="m6.1 6.3-1.7-3a.65.65 0 0 1 1.13-.65l1.72 3a11.6 11.6 0 0 1 9.5 0l1.72-3a.65.65 0 0 1 1.13.65l-1.7 3C21.3 8.4 23.5 12 24 16H0c.5-4 2.7-7.6 6.1-9.7Z"/>
                    <circle cx="7" cy="12" r="1" className="art:fill-primary-foreground"/>
                    <circle cx="17" cy="12" r="1" className="art:fill-primary-foreground"/>
                  </svg>
                  {copy.secondaryCta.label}
                </motion.a>
              </div>
            </motion.div>
            <dl className="art:relative art:mx-auto art:mt-12 art:grid art:max-w-4xl art:grid-cols-2 art:justify-center art:gap-x-4 art:gap-y-9 art:@min-[768px]/artemis:mt-20 art:@min-[768px]/artemis:flex art:@min-[768px]/artemis:flex-wrap art:@min-[768px]/artemis:gap-x-0">
              {copy.stats.map((stat, i) => (<motion.div key={stat.label} className="art:flex art:min-w-0 art:flex-col art:items-center art:gap-3 art:text-center art:@min-[768px]/artemis:flex-1 art:@min-[768px]/artemis:basis-1/4 art:@min-[768px]/artemis:px-3" initial={{ opacity: 0, y: 12 }} animate={play || reduce ? { opacity: 1, y: 0 } : undefined} transition={reduce ? INSTANT : { duration: 0.6, delay: i * 0.07, ease: ARTEMIS_EASE_OUT }}>
                  <dt className="art:order-last art:text-xs art:text-foreground/75 art:@min-[768px]/artemis:text-sm art:dark:text-background/75">{stat.label}</dt>
                  <dd className="art:text-3xl art:font-medium art:tracking-tight art:tabular-nums art:@min-[768px]/artemis:text-4xl">
                    <NumberTicker value={stat.value} suffix={stat.suffix} play={play}/>
                  </dd>
                </motion.div>))}
            </dl>
          </div>
        </div>
      </section>
    </MotionConfig>);
}

// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
export function NumberTicker({ value, suffix = "", play = false }: {
    value: string;
    suffix?: string;
    play?: boolean;
}) { return <ArtemisRollingNumber key={play ? "started" : "waiting"} text={play ? value : value.replace(/\d/g, "0")} label={value + suffix} suffix={suffix} duration={1.2} stagger={.08} activation="mount"/>; }

"use client";
// @zeus-internal
import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisRollingNumberProps {
  text: string;
  duration?: number;
  stagger?: number;
  className?: string;
  reducedMotion?: boolean;
  blur?: boolean;
  activation?: "in-view" | "immediate" | "mount";
  amount?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  blurUpdatesOnly?: boolean;
  staggerDigitsOnly?: boolean;
}
function Wheel({ value, delay, duration, reduced, blur, fromZero, blurUpdatesOnly }: { value: string; delay: number; duration: number; reduced: boolean; blur: boolean; fromZero: boolean; blurUpdatesOnly: boolean }) {
  const rail = useRef<HTMLSpanElement>(null);
  const firstPaint = useRef(true);
  useEffect(() => {
    const initial = firstPaint.current;
    firstPaint.current = false;
    if (!rail.current) return;
    if (!blur || reduced || value === "0" && !blurUpdatesOnly) { rail.current.style.filter = "none"; return; }
    if (blurUpdatesOnly && initial) return;
    const playback = animate(rail.current, { filter: ["blur(10px)", "blur(0px)"] }, { duration: 0.32, delay, ease: ARTEMIS_EASE_OUT });
    return () => playback.stop();
  }, [value, blur, reduced, blurUpdatesOnly]);
  return <span className="art:relative art:inline-block" style={{ clipPath: "inset(0)", lineHeight: "1.1em", height: "1.1em", width: "1ch", textAlign: "center" }}>
    <span className="art:invisible">{value}</span>
    <motion.span ref={rail} className="art:absolute art:inset-x-0 art:top-0 art:flex art:flex-col art:items-center art:will-change-[transform,filter]" initial={fromZero && !reduced ? { y: 0 } : false} animate={{ y: `${-Number(value) * 11 / 10}em` }} transition={reduced ? { duration: 0 } : { duration, delay, ease: ARTEMIS_EASE_OUT }}>
      {Array.from({ length: 10 }, (_, digit) => <span key={digit} className="art:flex art:items-center art:justify-center art:leading-none" style={{ height: "1.1em" }}>{digit}</span>)}
    </motion.span>
  </span>;
}
export function ArtemisRollingNumber({ text, duration = 0.6, stagger = 0.02, className = "", reducedMotion, blur = false, activation = "in-view", amount = 0.6, prefix = "", suffix = "", label, blurUpdatesOnly = false, staggerDigitsOnly = false }: ArtemisRollingNumberProps) {
  const anchor = useRef<HTMLSpanElement>(null);
  const observed = useInView(anchor, { once: true, amount });
  const visible = activation !== "in-view" || observed;
  const preference = useReducedMotion() === true;
  const reduced = reducedMotion ?? preference;
  const [settled, setSettled] = useState(false);
  const firstText = useRef(text), changedSinceMount = useRef(false);
  if (text !== firstText.current) changedSinceMount.current = true;
  useEffect(() => {
    if (!visible || settled) return;
    const timer = setTimeout(() => setSettled(true), (duration + text.length * stagger) * 1000);
    return () => clearTimeout(timer);
  }, [visible, settled, duration, stagger, text.length]);
  return <span ref={anchor} className={`art:inline-flex art:items-baseline art:tabular-nums ${className}`}>
    <span className="art:sr-only">{label ?? prefix + text + suffix}</span>
    <span aria-hidden="true" className="art:inline-flex art:items-baseline">{prefix && <span>{prefix}</span>}{Array.from(text, (char, index) => /[0-9]/.test(char)
      ? <Wheel key={text.length - index} value={visible || reduced ? char : "0"} delay={settled || reduced || activation === "mount" && changedSinceMount.current ? 0 : (staggerDigitsOnly ? text.slice(0, index).replace(/\D/g, "").length : index) * stagger} duration={duration} reduced={reduced} blur={blur} fromZero={activation === "mount"} blurUpdatesOnly={blurUpdatesOnly}/>
      : <span key={text.length - index}>{char}</span>)}{suffix && <span>{suffix}</span>}</span>
  </span>;
}
